<?php

namespace Agent\AgentBundle\Repository;

/**
 * DiplomeRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ImputationRepository extends \Doctrine\ORM\EntityRepository
{
	public function testImputation($objet, $id){
		$qb = $this->createQueryBuilder('i')
		->where('i.objetImputation = :objet')
		->andWhere('i.objetId = :id')
		->andWhere('i.etatTraitement = 0')
		->setParameter('objet', $objet)
		->setParameter('id', $id);
		return $qb->getQuery()->getOneorNullResult()
		;
	}
}
